// Write your script here
window.isEditMode = false

function toggleEditMode() {
    window.isEditMode = !window.isEditMode;

    const button = document.getElementById('edit-profile-button');
    const buttonText = button?.querySelector('.__text_block__');

    // Sections that can be edited
    const editableSections = [
        '.fb-0966e37e',  // Introduction section header
        '.fb-45e507db',  // Introduction container
        '.fb-ec684e46',  // Work History section header
        '.fb-8ff8a7ff',  // Work History container
        '.fb-46120012',  // Education section header
        '.fb-7b13b0c5',  // Education container
    ];

    if (window.isEditMode) {
        // Enter edit mode
        if (buttonText) buttonText.textContent = 'Editing';
        document.body.classList.add('profile-edit-mode');

        // Show edit indicators on sections
        editableSections.forEach(selector => {
            const section = document.querySelector(selector);
            if (section) {
                section.classList.add('editing');
            }
        });

        // Add visual feedback
        button?.classList.add('active-edit');

    } else {
        // Exit edit mode
        if (buttonText) buttonText.textContent = 'Edit';
        document.body.classList.remove('profile-edit-mode');

        // Remove edit indicators
        editableSections.forEach(selector => {
            const section = document.querySelector(selector);
            if (section) {
                section.classList.remove('editing');
            }
        });

        button?.classList.remove('active-edit');
    }
}

function init() {
    const editButton = document.getElementById('edit-profile-button');
    if (editButton) {
        editButton.addEventListener('click', function(e) {
            e.preventDefault();
            e.stopPropagation();
            toggleEditMode();
        });
    }
}

init();
